    # 5. Objects & Object Methods (30 Qs)
    obj_items = [
        ("How do you create an object in JavaScript?", "Using object literal syntax {} (recommended), new Object(), or Object.create(prototype).", "Easy", "Practical", "const user = { name: 'Alice', age: 25 };", "Which approach is most common?"),
        ("What is the difference between dot notation and bracket notation for accessing object properties?", "Dot notation user.name requires valid identifier keys. Bracket notation user['first-name'] or user[dynamicKey] supports special characters, spaces, and dynamic variable keys.", "Easy", "Comparison", "const key = 'role';\nuser[key]; // Dynamic property access", "When is bracket notation mandatory?"),
        ("What does Object.keys(obj) return?", "It returns an array of the object's own enumerable string-keyed property names.", "Easy", "Concept", "Object.keys({ a: 1, b: 2 }); // ['a', 'b']", "What does Object.values return?"),
        ("What does Object.values(obj) return?", "It returns an array of the object's own enumerable property values.", "Easy", "Concept", "Object.values({ a: 1, b: 2 }); // [1, 2]", "What does Object.entries return?"),
        ("What does Object.entries(obj) return?", "It returns an array of the object's own enumerable [key, value] pairs.", "Easy", "Concept", "Object.entries({ a: 1 }); // [['a', 1]]", "What method reverses Object.entries?"),
        ("What does Object.fromEntries(iterable) do?", "It transforms an array of [key, value] pairs into a standard JavaScript object.", "Intermediate", "Practical", "const entries = [['a', 1], ['b', 2]];\nconst obj = Object.fromEntries(entries); // { a: 1, b: 2 }", "Can Object.fromEntries convert a Map to an object?"),
        ("What does Object.assign(target, ...sources) do?", "It copies all own enumerable properties from one or more source objects to a target object, returning the target object.", "Easy", "Practical", "const merged = Object.assign({}, obj1, obj2);", "Is Object.assign shallow or deep?"),
        ("What is the difference between a shallow copy and a deep copy of an object?", "A shallow copy duplicates only top-level properties; nested objects/arrays are still shared by reference. A deep copy recursively duplicates all nested objects/arrays completely.", "Intermediate", "Comparison", "const shallow = { ...original };\nconst deep = structuredClone(original);", "How do you make a deep copy in modern JS?"),
        ("What is the modern standard native method for deep copying objects in JavaScript?", "Use structuredClone(object).", "Intermediate", "Practical", "const copy = structuredClone(user);", "What did developers use before structuredClone?"),
        ("Why is JSON.parse(JSON.stringify(obj)) flawed for deep cloning?", "It cannot copy functions, undefined, Symbols, RegExp, Date objects (converted to strings), Maps, Sets, and throws errors on circular references.", "Intermediate", "Comparison", "", "Does structuredClone handle circular references?"),
        ("Does structuredClone handle circular references in JavaScript?", "Yes! structuredClone handles circular references, Maps, Sets, Dates, and ArrayBuffers correctly.", "Intermediate", "Concept", "const a = {}; a.self = a;\nconst clone = structuredClone(a); // Works!", "Can structuredClone clone DOM nodes or functions?"),
        ("What does the 'in' operator check on an object?", "The 'in' operator returns true if the specified property exists in the object OR anywhere in its prototype chain.", "Intermediate", "Concept", "'toString' in {}; // true (from Object.prototype)", "How do you check for own properties only?"),
        ("What is the difference between obj.hasOwnProperty('prop') and 'prop' in obj?", "hasOwnProperty checks only the object's own direct properties. 'in' checks both own properties and inherited prototype properties.", "Intermediate", "Comparison", "const o = {};\no.hasOwnProperty('toString'); // false\n'toString' in o; // true", "What is Object.hasOwn?"),
        ("Why was Object.hasOwn(obj, prop) introduced in ES2022 to replace obj.hasOwnProperty?", "Objects created with Object.create(null) do not inherit hasOwnProperty from Object.prototype, throwing TypeError if obj.hasOwnProperty is called. Object.hasOwn works safely on all objects.", "Intermediate", "Concept", "const clean = Object.create(null);\nObject.hasOwn(clean, 'key'); // Safe!", "Can hasOwnProperty be overridden on an object?"),
        ("What does Object.freeze() do to an object?", "It prevents adding new properties, removing existing properties, and changing property values or descriptors.", "Intermediate", "Concept", "const frozen = Object.freeze({ x: 1 });", "What does Object.isFrozen return?"),
        ("What is the difference between Object.freeze() and Object.seal()?", "Object.freeze() makes all properties read-only (cannot modify values). Object.seal() prevents adding or deleting properties, but ALLOWS modifying existing writable property values.", "Intermediate", "Comparison", "Object.seal(obj); // Can edit existing properties, cannot add/delete", "Which is more restrictive: freeze or seal?"),
        ("What does Object.preventExtensions(obj) do?", "It prevents new properties from ever being added to the object, but existing properties can still be modified or deleted.", "Intermediate", "Concept", "Object.preventExtensions(obj);", "What does Object.isExtensible return?"),
        ("What is a property descriptor in JavaScript?", "A property descriptor describes the attributes of an object property: value, writable, enumerable, and configurable.", "Advanced", "Concept", "Object.getOwnPropertyDescriptor(obj, 'prop');", "What does configurable: false mean?"),
        ("What does configurable: false mean in a property descriptor?", "The property cannot be deleted from the object, and its descriptor cannot be modified (except writable from true to false).", "Advanced", "Concept", "", "What does enumerable: false mean?"),
        ("What does enumerable: false mean in a property descriptor?", "The property will not appear in for...in loops, Object.keys(), or JSON.stringify().", "Advanced", "Concept", "", "How do you define a non-enumerable property?"),
        ("How do you define a property with specific descriptors on an object?", "Use Object.defineProperty(obj, prop, descriptor).", "Advanced", "Practical", "Object.defineProperty(user, 'id', {\n  value: 101,\n  writable: false,\n  enumerable: true\n});", "What method defines multiple properties at once?"),
        ("What are getters and setters in JavaScript objects?", "Getters (get prop()) and setters (set prop(val)) are accessor properties that bind object properties to functions executed when reading or assigning values.", "Intermediate", "Concept", "const user = {\n  first: 'John', last: 'Doe',\n  get fullName() { return `${this.first} ${this.last}`; }\n};", "Can a getter exist without a setter?"),
        ("What does Object.create(null) do and why is it useful?", "It creates a pure dictionary object with no prototype (prototype is null), meaning it inherits no methods like toString or hasOwnProperty, preventing prototype pollution.", "Intermediate", "Practical", "const dict = Object.create(null);", "What is dict.__proto__?"),
        ("Objects MCQ: Which method creates a deep copy natively in modern JavaScript?", "Option C is correct. structuredClone() is the standard deep clone API.", "Easy", "MCQ", "", {"A": "Object.assign()", "B": "Spread operator {...obj}", "C": "structuredClone()", "D": "Object.clone()"}, "C", "Can structuredClone clone functions?"),
        ("Objects MCQ: What is the return value of Object.isFrozen(Object.freeze({}))?", "Option A is correct. Object.freeze returns the frozen object, so isFrozen is true.", "Easy", "MCQ", "", {"A": "true", "B": "false", "C": "undefined", "D": "TypeError"}, "A", "Can you unfreeze an object in JS?"),
        ("Objects MCQ: Which method safely checks for an own property even on Object.create(null) objects?", "Option D is correct. Object.hasOwn(obj, prop) was added in ES2022.", "Intermediate", "MCQ", "", {"A": "obj.hasOwnProperty()", "B": "'prop' in obj", "C": "obj.hasProp()", "D": "Object.hasOwn(obj, prop)"}, "D", "Why did obj.hasOwnProperty fail on Object.create(null)?"),
        ("Objects Debugging: Why does delete obj.length return false on an array?", "length on Array is a non-configurable property ({ configurable: false }) and cannot be deleted.", "Intermediate", "Debugging", "const arr = [1, 2];\ndelete arr.length; // false", "What does delete return when it fails in strict mode?"),
        ("Objects Output: What is logged by: const a = { n: 1 }; const b = a; a.x = a = { n: 2 }; console.log(a.x, b.x);?", "Output: undefined { n: 2 }. Property lookup a.x is resolved on the original object referenced by b before assignment occurs.", "Advanced", "Output", "const a = { n: 1 };\nconst b = a;\na.x = a = { n: 2 };\nconsole.log(a.x, b.x);", "Why is b.x set to { n: 2 }?"),
        ("Objects Coding: Write a function to check if an object is completely empty {}.", "function isEmpty(obj) { return Object.keys(obj).length === 0 && obj.constructor === Object; }", "Easy", "Coding", "function isEmpty(obj) {\n  return Object.keys(obj).length === 0;\n}", "Does this check for non-enumerable properties?"),
        ("Objects Coding: Write a function to invert keys and values of an object.", "function invert(obj) { return Object.fromEntries(Object.entries(obj).map(([k, v]) => [v, k])); }", "Intermediate", "Coding", "function invert(obj) {\n  return Object.fromEntries(\n    Object.entries(obj).map(([k, v]) => [v, k])\n  );\n}", "What happens if duplicate values exist?")
    ]
