        ("What does a constructor return if it explicitly returns an object (e.g. return { b: 2 })?", "The explicitly returned object is returned, overriding the 'this' instance.", "Intermediate", "Concept", "function Bar() { this.a = 1; return { b: 2 }; }\nconsole.log(new Bar()); // { b: 2 }", "Why does this happen?"),
